const crypto = require('crypto');
const runId = $('Initialize Run & Profile').first()?.json?.run_id || 'unknown';
const items = $input.all();

const seenFingerprints = new Set();
const normalizedJobs = [];

for (const it of items) {
  const job = it.json;
  if (!job || job.is_error || job.is_empty || !job.job_title || !job.company_name || !job.application_url) {
    continue;
  }

  if (!job.application_url.startsWith('http://') && !job.application_url.startsWith('https://')) {
    continue;
  }

  let fingerprintRaw;
  if (job.source && job.source_job_id) {
    fingerprintRaw = `${job.source}:${job.source_job_id}`.toLowerCase().trim();
  } else {
    const normCompany = (job.company_name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const normTitle = (job.job_title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const normLoc = (job.location || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const normUrl = (job.canonical_url || job.application_url || '').toLowerCase().trim();
    fingerprintRaw = `${normCompany}:${normTitle}:${normLoc}:${normUrl}`;
  }

  const fp = crypto.createHash('sha256').update(fingerprintRaw).digest('hex');
  if (seenFingerprints.has(fp)) {
    continue;
  }
  seenFingerprints.add(fp);

  normalizedJobs.push({
    json: {
      ...job,
      run_id: runId,
      fingerprint: fp
    }
  });
}

return normalizedJobs.length > 0 ? normalizedJobs : [{ json: { is_empty: true, run_id: runId } }];

const profile = $('Initialize Run & Profile').first()?.json?.profile || {};
const runId = $('Initialize Run & Profile').first()?.json?.run_id || 'unknown';
const targetTitles = (profile.target_titles || []).map(t => t.toLowerCase());
const targetKeywords = (profile.target_keywords || []).map(k => k.toLowerCase());
const excludeKeywords = (profile.exclude_keywords || []).map(k => k.toLowerCase());

const items = $input.all();
const candidates = [];

for (const it of items) {
  const job = it.json;
  if (!job.fingerprint || job.skipped) continue;

  // If already notified or already evaluated, skip
  if (job.telegram_sent === true || job.match_status === 'MATCHED' || job.match_status === 'REJECTED') {
    continue;
  }

  const titleLower = (job.job_title || '').toLowerCase();

  // 1. Exclude keywords
  let excludedReason = null;
  for (const ex of excludeKeywords) {
    if (titleLower.includes(ex)) {
      excludedReason = `Title contains excluded term: '${ex}'`;
      break;
    }
  }
  if (excludedReason) {
    continue;
  }

  // 2. Target title / keyword match
  const titleMatches = targetTitles.some(t => titleLower.includes(t)) ||
                       targetKeywords.some(k => titleLower.includes(k));

  if (!titleMatches) {
    continue;
  }

  let relevanceScore = 0;
  // Target title match
  if (targetTitles.some(t => titleLower.includes(t))) relevanceScore += 15;
  // Core tech keywords in title
  if (['software', 'backend', 'full stack', 'fullstack', 'ai engineer', 'platform', 'cloud', 'devops', 'developer'].some(k => titleLower.includes(k))) relevanceScore += 10;
  // Location preference match
  const locLower = (job.location || '').toLowerCase();
  if (job.remote_type === 'Remote' || ['remote', 'india', 'bangalore', 'worldwide', 'usa', 'canada', 'uk'].some(l => locLower.includes(l))) relevanceScore += 5;
  // Preferred company boost
  const compLower = (job.company_name || '').toLowerCase();
  if (['gitlab', 'ramp', 'supabase', 'maintainx'].some(c => compLower.includes(c))) relevanceScore += 5;

  candidates.push({
    relevance: relevanceScore,
    json: {
      ...job,
      run_id: runId,
      prefilter_passed: true,
      has_candidates: true
    }
  });
}

if (candidates.length === 0) {
  return [{ json: { run_id: runId, has_candidates: false } }];
}

// Sort candidates descending by relevance heuristic
candidates.sort((a, b) => b.relevance - a.relevance);

// Cap candidates for AI evaluation to 3 per run for cost, rate limits, and latency
return candidates.slice(0, 3).map(c => ({ json: c.json }));

