const minScore = $('Initialize Run & Profile').first()?.json?.profile?.min_match_score || 70;
let rawJob = null;
try {
  rawJob = $('Prepare AI Matching Prompt').item?.json;
} catch (e) {}
if (!rawJob) {
  rawJob = $('Prepare AI Matching Prompt').last()?.json || $('Prepare AI Matching Prompt').first()?.json;
}
const aiResponse = $input.first()?.json;

let parsed = null;
let rawText = '';

try {
  if (aiResponse && aiResponse.text) {
    rawText = aiResponse.text;
  } else if (aiResponse && aiResponse.response) {
    rawText = aiResponse.response;
  } else if (aiResponse && typeof aiResponse === 'string') {
    rawText = aiResponse;
  } else if (aiResponse && aiResponse.error) {
    throw new Error(aiResponse.error.message || 'AI request error');
  }

  let cleanJson = rawText.trim();
  if (cleanJson.startsWith('```json')) {
    cleanJson = cleanJson.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleanJson.startsWith('```')) {
    cleanJson = cleanJson.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }

  const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleanJson = jsonMatch[0];
  }

  parsed = JSON.parse(cleanJson);
} catch(e) {
  return [{
    json: {
      ...rawJob,
      match_status: 'AI_MATCH_ERROR',
      score: 0,
      reasons: ['AI parsing error: ' + e.message],
      matched_skills: [],
      missing_skills: [],
      is_qualifying: false
    }
  }];
}

const score = typeof parsed.score === 'number' ? parsed.score : 0;
const isMatch = parsed.match === true && score >= minScore;
const matchStatus = isMatch ? 'MATCHED' : 'REJECTED';

return [{
  json: {
    ...rawJob,
    match_status: matchStatus,
    score: score,
    reasons: Array.isArray(parsed.reasons) ? parsed.reasons : [],
    matched_skills: Array.isArray(parsed.matched_skills) ? parsed.matched_skills : [],
    missing_skills: Array.isArray(parsed.missing_skills) ? parsed.missing_skills : [],
    ai_details: parsed,
    is_qualifying: isMatch && !rawJob.telegram_sent
  }
}];

const chatId = $('Initialize Run & Profile').first()?.json?.profile?.telegram_chat_id || '617149298';
const job = $input.first()?.json;

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const title = escapeHtml(job.job_title);
const company = escapeHtml(job.company_name);
const location = escapeHtml(job.location || 'Remote');
const remoteType = escapeHtml(job.remote_type || 'Remote');
const empType = escapeHtml(job.employment_type || 'Full-time');
const score = job.profile_match_score || 0;
const reasons = Array.isArray(job.match_details?.reasons) ? job.match_details.reasons : [job.match_reason || 'Profile criteria matched'];
const matchedSkills = Array.isArray(job.match_details?.matched_skills) ? job.match_details.matched_skills.join(', ') : '';
const missingSkills = Array.isArray(job.match_details?.missing_skills) && job.match_details.missing_skills.length > 0 ? job.match_details.missing_skills.join(', ') : 'None';
const appUrl = job.application_url;

let messageHtml = `🚀 <b>NEW JOB MATCH</b> (Score: <b>${score}/100</b>)\n\n`;
messageHtml += `💼 <b>${title}</b>\n`;
messageHtml += `🏢 <b>${company}</b>\n`;
messageHtml += `📍 <b>${location}</b> (${remoteType})\n`;
messageHtml += `👔 <b>${empType}</b>\n\n`;

messageHtml += `🎯 <b>Why It Matches:</b>\n`;
for (const r of reasons.slice(0, 3)) {
  messageHtml += `• ${escapeHtml(r)}\n`;
}
messageHtml += `\n`;

if (matchedSkills) {
  messageHtml += `✅ <b>Matched Skills:</b> ${escapeHtml(matchedSkills)}\n`;
}
if (missingSkills && missingSkills !== 'None') {
  messageHtml += `⚠️ <b>Missing Skills:</b> ${escapeHtml(missingSkills)}\n`;
}

messageHtml += `\n🔗 <a href="${escapeHtml(appUrl)}"><b>View & Apply</b></a>\n`;
messageHtml += `<i>Source: ${escapeHtml(job.source || 'Aggregator')} | Ref: ${job.fingerprint.substring(0, 10)}</i>`;

return [{
  json: {
    chatId: chatId,
    messageText: messageHtml,
    fingerprint: job.fingerprint,
    job_id: job.id
  }
}];
